<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>DVD Logo Bouncer</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        html, body {
            height: 100%;
            overflow: hidden;
            background: #2b2b2b;
            font-family: Arial, sans-serif;
        }

        #logo {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            color: #dcdcdc;
            font-size: 48px;
            font-weight: bold;
            white-space: nowrap;
            user-select: none;
        }

        #logo span {
            background: #ffdd00;
            color: #1a1a1a;
            padding: 2px 6px;
            border-radius: 4px;
        }
    </style>
</head>
<body>
    <div id="logo">DVD <span>DVD</span></div>

    <script>
        const logo = document.getElementById('logo');

        // Physics properties
        let x, y, vx, vy;

        function init() {
            const width = window.innerWidth;
            const height = window.innerHeight;
            const size = 120; // Approximate size of the logo element

            x = width / 2 - size / 2;
            y = height / 2 - size / 2;

            // Initial velocity (straight line)
            vx = 3;   // horizontal speed
            vy = 1.5; // vertical speed

            update();
        }

        function update() {
            const width = window.innerWidth;
            const height = window.innerHeight;
            const size = logo.offsetWidth;

            x += vx;
            y += vy;

            // Bounce off walls (horizontal)
            if (x <= 0) {
                x = 0;
                vx = Math.abs(vx);
            } else if (x + size >= width) {
                x = width - size;
                vx = -Math.abs(vx);
            }

            // Bounce off walls (vertical)
            if (y <= 0) {
                y = 0;
                vy = Math.abs(vy);
            } else if (y + size >= height) {
                y = height - size;
                vy = -Math.abs(vy);
            }

            logo.style.left = x + 'px';
            logo.style.top = y + 'px';
        }

        // Run on startup and resize
        window.addEventListener('load', init);
        window.addEventListener('resize', init);

        // Animate at 60fps
        function animate() {
            update();
            requestAnimationFrame(animate);
        }

        animate();
    </script>
</body>
</html>
```

**How it works:**

- The DVD logo is a `<div>` positioned absolutely and moved each frame via JavaScript.
- Each animation frame, the position (`x`, `y`) advances by its velocity (`vx`, `vy`).
- When the logo hits any wall (left, right, top, or bottom), the corresponding velocity component reverses sign — so it bounces off walls while keeping its speed and continuing to travel.
- No gravity is applied, so it travels in a straight diagonal line until it collides with a wall.

**To use it:** Save the code as `dvd-logo.html` and open it in any web browser. The logo will bounce around the screen continuously.

